///  Transport Facility Node
class TFN {
  TFN._(this._bc, this._bcOffset);
  factory TFN(List<int> bytes) {
    final rootRef = fb.BufferContext.fromBytes(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<TFN> reader = _TFNReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  ///  Publisher-stable identifier for this facility record.
  String? get ID => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 4);
  ///  `$GNP.ID` of the gazetteer place carrying this facility's name set
  ///  and location. Location is joined, never re-published here.
  String? get PLACE_ID => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 6);
  String? get placeId => PLACE_ID;
  ///  Kind of facility.
  tfnFacilityType get FACILITY_TYPE => tfnFacilityType.fromValue(const fb.Int8Reader().vTableGet(_bc, _bcOffset, 8, 0));
  tfnFacilityType get facilityType => FACILITY_TYPE;
  ///  Operational display name, verbatim, when it differs from the place
  ///  name in `$GNP`.
  String? get NAME => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 10);
  ///  Every designator the facility answers to, scheme-tagged.
  List<TFNDesignator>? get DESIGNATORS => const fb.ListReader<TFNDesignator>(TFNDesignator.reader).vTableGetNullable(_bc, _bcOffset, 12);
  ///  ISO 3166-1 alpha-2 country code, uppercase, as the source states it.
  String? get COUNTRY_CODE => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 14);
  String? get countryCode => COUNTRY_CODE;
  ///  Field or reference elevation, metres above mean sea level as the
  ///  source publishes it. Zero means unpublished, never sea level; a
  ///  facility at sea level is distinguished by ELEVATION_PUBLISHED.
  double get ELEVATION_M => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 16, 0.0);
  double get elevationM => ELEVATION_M;
  ///  ELEVATION_M carries a published value.
  bool get ELEVATION_PUBLISHED => const fb.BoolReader().vTableGet(_bc, _bcOffset, 18, false);
  bool get elevationPublished => ELEVATION_PUBLISHED;
  ///  Magnetic variation at the facility, degrees, positive east, as the
  ///  source publishes it. NaN when unpublished.
  double get MAGNETIC_VARIATION_DEG => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 20, 0.0);
  double get magneticVariationDeg => MAGNETIC_VARIATION_DEG;
  ///  The operating surfaces of the facility.
  List<TFNOperatingSurface>? get OPERATING_SURFACES => const fb.ListReader<TFNOperatingSurface>(TFNOperatingSurface.reader).vTableGetNullable(_bc, _bcOffset, 22);
  List<TFNOperatingSurface>? get operatingSurfaces => OPERATING_SURFACES;
  ///  Maximum vessel draft the facility accepts, metres.
  double get MAXIMUM_DRAFT_M => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 24, 0.0);
  double get maximumDraftM => MAXIMUM_DRAFT_M;
  ///  Depth of water at the principal anchorage, metres.
  double get ANCHORAGE_DEPTH_M => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 26, 0.0);
  double get anchorageDepthM => ANCHORAGE_DEPTH_M;
  ///  Harbor type token, verbatim as the source publishes it.
  String? get HARBOR_TYPE => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 28);
  String? get harborType => HARBOR_TYPE;
  ///  Shelter afforded token, verbatim as the source publishes it.
  String? get SHELTER_AFFORDED => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 30);
  String? get shelterAfforded => SHELTER_AFFORDED;
  ///  Dataset lineage and licence. Required.
  TFNProvenance? get SOURCE => TFNProvenance.reader.vTableGetNullable(_bc, _bcOffset, 32);

  @override
  String toString() {
    return 'TFN{ID: ${ID}, placeId: ${placeId}, facilityType: ${facilityType}, NAME: ${NAME}, DESIGNATORS: ${DESIGNATORS}, countryCode: ${countryCode}, elevationM: ${elevationM}, elevationPublished: ${elevationPublished}, magneticVariationDeg: ${magneticVariationDeg}, operatingSurfaces: ${operatingSurfaces}, maximumDraftM: ${maximumDraftM}, anchorageDepthM: ${anchorageDepthM}, harborType: ${harborType}, shelterAfforded: ${shelterAfforded}, SOURCE: ${SOURCE}}';
  }
}

class _TFNReader extends fb.TableReader<TFN> {
  const _TFNReader();

  @override
  TFN createObject(fb.BufferContext bc, int offset) =>
    TFN._(bc, offset);
}

class TFNBuilder {
  TFNBuilder(this.fbBuilder);

  final fb.Builder fbBuilder;

  void begin() {
    fbBuilder.startTable(15);
  }

  int addIdOffset(int? offset) {
    fbBuilder.addOffset(0, offset);
    return fbBuilder.offset;
  }
  int addPlaceIdOffset(int? offset) {
    fbBuilder.addOffset(1, offset);
    return fbBuilder.offset;
  }
  int addFacilityType(tfnFacilityType? FACILITY_TYPE) {
    fbBuilder.addInt8(2, FACILITY_TYPE?.value);
    return fbBuilder.offset;
  }
  int addNameOffset(int? offset) {
    fbBuilder.addOffset(3, offset);
    return fbBuilder.offset;
  }
  int addDesignatorsOffset(int? offset) {
    fbBuilder.addOffset(4, offset);
    return fbBuilder.offset;
  }
  int addCountryCodeOffset(int? offset) {
    fbBuilder.addOffset(5, offset);
    return fbBuilder.offset;
  }
  int addElevationM(double? ELEVATION_M) {
    fbBuilder.addFloat64(6, ELEVATION_M);
    return fbBuilder.offset;
  }
  int addElevationPublished(bool? ELEVATION_PUBLISHED) {
    fbBuilder.addBool(7, ELEVATION_PUBLISHED);
    return fbBuilder.offset;
  }
  int addMagneticVariationDeg(double? MAGNETIC_VARIATION_DEG) {
    fbBuilder.addFloat64(8, MAGNETIC_VARIATION_DEG);
    return fbBuilder.offset;
  }
  int addOperatingSurfacesOffset(int? offset) {
    fbBuilder.addOffset(9, offset);
    return fbBuilder.offset;
  }
  int addMaximumDraftM(double? MAXIMUM_DRAFT_M) {
    fbBuilder.addFloat64(10, MAXIMUM_DRAFT_M);
    return fbBuilder.offset;
  }
  int addAnchorageDepthM(double? ANCHORAGE_DEPTH_M) {
    fbBuilder.addFloat64(11, ANCHORAGE_DEPTH_M);
    return fbBuilder.offset;
  }
  int addHarborTypeOffset(int? offset) {
    fbBuilder.addOffset(12, offset);
    return fbBuilder.offset;
  }
  int addShelterAffordedOffset(int? offset) {
    fbBuilder.addOffset(13, offset);
    return fbBuilder.offset;
  }
  int addSourceOffset(int? offset) {
    fbBuilder.addOffset(14, offset);
    return fbBuilder.offset;
  }

  int finish() {
    return fbBuilder.endTable();
  }
