    String? HARBOR_TYPE,
    String? harborType,
    String? SHELTER_AFFORDED,
    String? shelterAfforded,
    TFNProvenanceObjectBuilder? SOURCE,
  })
      : _ID = ID,
        _PLACE_ID = placeId ?? PLACE_ID,
        _FACILITY_TYPE = facilityType ?? FACILITY_TYPE,
        _NAME = NAME,
        _DESIGNATORS = DESIGNATORS,
        _COUNTRY_CODE = countryCode ?? COUNTRY_CODE,
        _ELEVATION_M = elevationM ?? ELEVATION_M,
        _ELEVATION_PUBLISHED = elevationPublished ?? ELEVATION_PUBLISHED,
        _MAGNETIC_VARIATION_DEG = magneticVariationDeg ?? MAGNETIC_VARIATION_DEG,
        _OPERATING_SURFACES = operatingSurfaces ?? OPERATING_SURFACES,
        _MAXIMUM_DRAFT_M = maximumDraftM ?? MAXIMUM_DRAFT_M,
        _ANCHORAGE_DEPTH_M = anchorageDepthM ?? ANCHORAGE_DEPTH_M,
        _HARBOR_TYPE = harborType ?? HARBOR_TYPE,
        _SHELTER_AFFORDED = shelterAfforded ?? SHELTER_AFFORDED,
