    final int? SHELTER_AFFORDEDOffset = _SHELTER_AFFORDED == null ? null
        : fbBuilder.writeString(_SHELTER_AFFORDED!);
    final int? SOURCEOffset = _SOURCE?.getOrCreateOffset(fbBuilder);
    fbBuilder.startTable(15);
    fbBuilder.addOffset(0, IDOffset);
    fbBuilder.addOffset(1, PLACE_IDOffset);
    fbBuilder.addInt8(2, _FACILITY_TYPE?.value);
    fbBuilder.addOffset(3, NAMEOffset);
